const dot=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0),sub=(a,b)=>a.map((v,i)=>v-b[i]);
export class PointDetent{
 constructor(points,initial,{capture=.035,release=.1}={}){this.points=points;this.previous=initial.slice();this.capture=capture;this.release=release;this.used=new Set();this.active=null;this.holding=false;this.label='';}
 update(raw,axes,enabled=true){this.holding=false;this.label='';if(!enabled){if(this.active!==null)this.used.add(this.active);this.active=null;this.previous=raw.slice();return raw;}if(this.active!==null){const p=this.points[this.active];if(Math.hypot(...sub(raw,p.p))<=this.release){this.holding=true;this.label=p.label;this.previous=raw.slice();return p.p.slice();}this.used.add(this.active);this.active=null;}const delta=sub(raw,this.previous),length2=dot(delta,delta);let best=Infinity,index=null;this.points.forEach((p,i)=>{if(this.used.has(i))return;const difference=sub(p.p,raw),residual=difference.slice();for(const axis of axes){const along=dot(difference,axis);for(let k=0;k<3;k++)residual[k]-=along*axis[k];}if(Math.hypot(...residual)>1e-5)return;const t=length2?Math.max(0,Math.min(1,dot(sub(p.p,this.previous),delta)/length2)):1;const closest=this.previous.map((v,k)=>v+t*delta[k]);const distance=Math.hypot(...sub(p.p,closest)),initialDistance=Math.hypot(...sub(p.p,this.previous));if(distance<=this.capture&&initialDistance>1e-7&&distance<best){best=distance;index=i;}});this.previous=raw.slice();if(index!==null){this.active=index;this.holding=true;this.label=this.points[index].label;return this.points[index].p.slice();}return raw;}
}
